 ) as source(activity_key,revision,drive_source_id) loop
 select count(*),min(id::text)::uuid into n,cid from public.content_items where content_type='BOOK' and owner_scope='GLOBAL_RAIZES' and editorial_status='PUBLISHED' and published_at is not null and metadata->'official_edition'->>'source_id'=m.drive_source_id;
 if n<>1 then raise exception 'MISSION_SOURCE_BINDING_NOT_UNIQUE: %',m.activity_key;end if;
 select count(*),min(id::text)::uuid into n,rid from mission_private.revisions where activity_key=m.activity_key and revision=m.revision and owner_auth_id is null;
 if n<>1 then raise exception 'MISSION_SOURCE_REVISION_NOT_UNIQUE: %',m.activity_key;end if;
 select * into existing from mission_private.source_bindings where root_revision_id=rid;
 if found then if existing.source_content_item_id<>cid or existing.source_reference<>m.drive_source_id then raise exception 'MISSION_SOURCE_BINDING_CONFLICT';end if;
 else insert into mission_private.source_bindings(root_revision_id,source_content_item_id,source_reference,verification_batch) values(rid,cid,m.drive_source_id,'v28_20261108_exact_book_reference');end if;
 end loop;
end $bindings$;
